#!/usr/bin/env python3
"""Kinematic-only ANYmal D URDF with the Unitree joint names that TRAIL's closed-form leg kinematics expects.

common/leg_kinematics.py reads {FL,FR,RL,RR}_{hip,thigh,calf}_joint and {leg}_foot_fixed (child offset xyz/rpy in
the parent, rotation about `axis` at the child origin). The ANYmal chain has fixed frames between the actuated
joints (HAA_drive, hip_fixed, HFE_output, HFE_drive, thigh_fixed, KFE_drive, shank_fixed); they are folded into
the origin of the next revolute joint. Leg map: LF->FL, RF->FR, LH->RL, RH->RR; HAA->hip, HFE->thigh, KFE->calf.
The foot point ({leg}_foot_fixed) is the centre of the foot collision sphere (FOOT frame + sphere origin, radius in
the comment), as the Unitree models; imu_joint keeps the IMU pose of the source (position and rotation in the base).

Generated robots/anymal/model/anymal_d_kinematic.urdf from robots/anymal/model/anymal.urdf
(ANYbotics/anymal_d_simple_description).

usage: make_kinematic_urdf.py [<anymal.urdf> <out.urdf>]   (default: the robots/anymal/model files)
"""
import sys
import xml.etree.ElementTree as ET
from pathlib import Path

import numpy as np
from scipy.spatial.transform import Rotation as R

LEGS = {'LF': 'FL', 'RF': 'FR', 'LH': 'RL', 'RH': 'RR'}


def load(path):
    root = ET.parse(path).getroot()
    by_child = {}
    for j in root.findall('joint'):
        o = j.find('origin')
        xyz = np.array([float(v) for v in (o.get('xyz') if o is not None else '0 0 0').split()])
        rpy = np.array([float(v) for v in (o.get('rpy') if o is not None else '0 0 0').split()])
        T = np.eye(4); T[:3, :3] = R.from_euler('xyz', rpy).as_matrix(); T[:3, 3] = xyz
        a = j.find('axis')
        by_child[j.find('child').get('link')] = dict(name=j.get('name'), type=j.get('type'), parent=j.find('parent').get('link'),
                                                     T=T, axis=np.array([float(v) for v in a.get('xyz').split()]) if a is not None else None)
    return by_child


def chain(by_child, link, stop):
    """Joints from `stop` (exclusive) down to `link`, root first."""
    out = []
    while link != stop:
        j = by_child[link]; out.append(j); link = j['parent']
    return out[::-1]


def foot_sphere(src, link):
    """(origin xyz in the link frame, radius) of the sphere collision of `link`."""
    root = ET.parse(src).getroot()
    for l in root.findall('link'):
        if l.get('name') == link:
            for c in l.findall('collision'):
                sph = c.find('geometry/sphere')
                if sph is not None:
                    o = c.find('origin')
                    return np.array([float(v) for v in (o.get('xyz') if o is not None else '0 0 0').split()]), float(sph.get('radius'))
    raise ValueError(f'{link}: no sphere collision')


def main(src, dst):
    J = load(src)
    lines = ['<?xml version="1.0"?>', f'<!-- generated by TRAIL data_scripts/make_kinematic_urdf.py from {Path(src).name}: kinematics only, Unitree names -->',
             '<robot name="anymal_d_kinematic">', '  <link name="base"/>']
    imu = J['imu_link']
    lines.append(_joint('imu_joint', 'fixed', 'base', 'imu_link', imu['T'], None)); lines.append('  <link name="imu_link"/>')
    for a, u in LEGS.items():
        parent = 'base'
        segments = [('hip', f'{a}_HIP'), ('thigh', f'{a}_THIGH'), ('calf', f'{a}_SHANK'), ('foot', f'{a}_FOOT')]
        prev_link = 'base'
        for name, link in segments:
            joints = chain(J, link, prev_link)
            T = np.eye(4)
            for j in joints:
                T = T @ j['T']
            last = joints[-1]
            if name == 'foot':
                assert all(j['type'] == 'fixed' for j in joints)
                centre, radius = foot_sphere(src, link)
                S = np.eye(4); S[:3, 3] = centre
                T = T @ S
                lines.append(f'  <!-- {u} foot point = {link} collision sphere centre, radius {radius} m -->')
                lines.append(_joint(f'{u}_foot_fixed', 'fixed', parent, f'{u}_foot', T, None))
                lines.append(f'  <link name="{u}_foot"/>')
            else:
                assert last['type'] == 'revolute' and all(j['type'] == 'fixed' for j in joints[:-1])
                assert np.allclose(last['T'], np.eye(4))      # revolute joints sit at the child origin
                lines.append(_joint(f'{u}_{name}_joint', 'revolute', parent, f'{u}_{name}', T, last['axis']))
                lines.append(f'  <link name="{u}_{name}"/>')
                parent = f'{u}_{name}'
            prev_link = link
    lines.append('</robot>')
    open(dst, 'w').write('\n'.join(lines) + '\n')


def _joint(name, typ, parent, child, T, axis):
    xyz = ' '.join(f'{v:.10g}' for v in T[:3, 3]); rpy = ' '.join(f'{v:.15g}' for v in R.from_matrix(T[:3, :3]).as_euler('xyz'))
    ax = f'\n    <axis xyz="{" ".join(f"{v:g}" for v in axis)}"/>' if axis is not None else ''
    lim = '\n    <limit lower="-9.42" upper="9.42" effort="100" velocity="20"/>' if typ == 'revolute' else ''
    return f'  <joint name="{name}" type="{typ}">\n    <parent link="{parent}"/>\n    <child link="{child}"/>\n    <origin xyz="{xyz}" rpy="{rpy}"/>{ax}{lim}\n  </joint>'


if __name__ == '__main__':
    from pathlib import Path
    model = Path(__file__).resolve().parents[4] / 'robots' / 'anymal' / 'model'
    args = sys.argv[1:3] or [str(model / 'anymal.urdf'), str(model / 'anymal_d_kinematic.urdf')]
    main(*args)
